import sys

def main():
    # Read all lines from stdin and strip whitespace, collecting non-empty labels
    labels = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            labels.append(line)

    # Determine unique categories in the order of their first occurrence
    unique_categories = []
    seen = set()
    for label in labels:
        if label not in seen:
            seen.add(label)
            unique_categories.append(label)

    # Create the one-hot encoded matrix
    matrix = []
    num_categories = len(unique_categories)
    for label in labels:
        row = []
        for cat in unique_categories:
            row.append(1 if cat == label else 0)
        matrix.append(row)

    # Print the matrix, each row on a separate line with space-separated values
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()

