def watch_file(
    path: Path,
    callback: callable[[Path], None],
) -> None:
    """Start monitoring the directory containing the given file path for changes and invoke the callback whenever the file is modified, created, or deleted.

    Args:
        path (Path): The file path to monitor.
        callback (callable): A function that takes a Path object as its argument when a change is detected.

    Raises:
        NotADirectoryError: If the directory containing the file does not exist.
        RuntimeError: If inotify setup fails (e.g., permission issues).
    """
    dir_to_watch = path.parent
    if not dir_to_watch.exists():
        raise NotADirectoryError(f"The directory '{dir_to_watch}' does not exist.")

    mask = inotify.IN MODIFY | inotify.IN_CREATE | inotify.IN_DELETE

    def event_handler(event):
        if event.path == path:
            callback(event.path)

    wm = inotify.WatchManager()
    try:
        wm.add_watching(dir_to_watch, mask

