import time

def throttle(func):
    last_run = None  # Stores the timestamp of the last function execution

    def wrapper(*args, **kwargs):
        nonlocal last_run
        now = time.time()
        if last_run is None or (now - last_run) >= 60:
            result = func(*args, **kwargs)
            last_run = now
            return result
        else:
            return None  # Suppress the call if within the allowed time window

    return wrapper

