import ipaddress

def list_hosts(subnet):
    """List all host addresses in the given IPv4 subnet."""
    try:
        net = ipaddress.IPv4Network(subnet, strict=True)
    except ValueError as e:
        return f"Error: Invalid subnet '{subnet}' – {str(e)}"

    hosts = [str(host) for host in net.hosts()]
    return '\n'.join(hosts)

