    factors = {}
    while num % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        num = num // 2
    d = 3
    while d * d <= num:
        while num % d == 0:
            factors[d] = factors.get(d, 0) + 1
            num = num // d
        d += 2
    if num > 2:
        factors[num] = 1
    return factors

