def topological_sort(dependencies):
    # Collect all unique tasks from the dependencies
    tasks = set()
    for task, dependency in dependencies:
        tasks.add(task)
        tasks.add(dependency)
    all_tasks = list(tasks)

    # Initialize in_degree and adjacency list
