    adjacency = {task: [] for task in all_tasks}

    # Populate the adjacency list and in_degree
    for task, dependency in dependencies:
        adjacency[dependency].append(task)  # edge from dependency to task
        in_degree[task] += 1

    # Initialize queue with nodes having in_degree 0
    queue = deque()
    for task in all_tasks:
        if in_degree[task] == 0:
            queue.append(task)

    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        # Reduce the in_degree of all neighbors
        for neighbor in adjacency[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all tasks were included (no cycles)
    if len(order) != len(all_tasks):
        raise ValueError("Cycle detected; no valid execution order possible")

    return order

