def watch_file(file_path, callback):
    import os
    from watchdog.events import FileCreatedEvent, FileModifiedEvent
    from watchdog.observers import Observer
    import time

    # Extract the directory from the file path
    directory = os.path.dirname(file_path)
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory {directory} does not exist. Please create it first.")

    class CustomEventHandler(watchdog.events.EventHandler):
        def __init__(self, callback, target_path):
            self.callback = callback
            self.target_path = target_path

