from collections import deque

def topo_sort(task_pairs):
    # Step 1: Collect all unique nodes (tasks and dependencies)
    all_tasks = set()
    for task, dep in task_pairs:
        all_tasks.add(task)
        all_tasks.add(dep)
    all_nodes = list(all_tasks)

    # Step 2: Build adjacency list and in-degree dictionary
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for task, dep in task_pairs:
        # Add edge from dependency to task
        adj[dep].append(task)
        in_degree[task] += 1

    # Step 3: Initialize queue with nodes of in-degree 0
    queue = deque()
    for node in all_nodes:
        if in_degree[node] == 0:
            queue.append(node)

    # Step 4: Process nodes in the queue
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 5: Check if all nodes were included (no cycle)
    if len(order) != len(all_nodes):
        raise ValueError("图有循环（graph has a cycle）")

    return order

