from collections import deque

def topo_sort(pairs):
    # Step 1: Collect all nodes and build the graph structure
    nodes = set()
    for task, dep in pairs:
        nodes.add(task)
        nodes.add(dep)

    # Initialize adjacency list and in-degree dictionary
    adjacency = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Populate adjacency and in_degree based on the pairs
    for task, dep in pairs:
        adjacency[dep].append(task)
        in_degree[task] += 1

    # Step 2: Apply Kahn's algorithm
    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adjacency[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check for cycles
    if len(order) != len(nodes):
        raise ValueError("Cycle detected")

    return order

