    if n < 2:
        return []

    factors = []

    # Handle the factor 2 separately
    if n % 2 == 0:
        count = 0
        while n % 2 == 0:
            count += 1
            n = n // 2
        factors.append((2, count))

    # Now n must be odd, start checking from 3
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            count = 0
            while n % divisor == 0:
