import pandas as pd

def standardize_column_by_group(df: pd.DataFrame, group_key: str, target_col: str) -> pd.DataFrame:
    # Check if required columns exist
    if group_key not in df.columns:
        raise ValueError(f"Group key '{group_key}' not present in the DataFrame")
    if target_col not in df.columns:
        raise ValueError(f"Target column '{target_col}' not present in the DataFrame")

    # Group the DataFrame by the group key
    grouped = df.groupby(group_key)
    result = []

    for name, subgroup in grouped:
        # Extract non-null values and calculate mean
        non_null = subgroup[target_col].dropna()
        if not non_null.any():
            # All entries are null; use default value (0)
            mean_val = 0.0
        else:
            mean_val = non_null.mean()

        # Fill missing values with the calculated mean
        subgroup[target_col] = subgroup[target_col].fillna(mean_val)
        result.append(subgroup)

    # Concatenate groups back into a single DataFrame
    return pd.concat(result, ignore_index=True)

