from datetime import datetime

def parse_log_entry(line: str) -> dict | None:
    stripped = line.strip()
    if not stripped:
        return None  # Skip empty lines

    parts = stripped.split()
    if len(parts) < 2:
        return None  # Not enough parts for a timestamp

    # Combine the first two parts to form the potential timestamp string
    timestamp_str = f"{parts[0]} {parts[1]}"

    # Attempt to parse the timestamp string
    try:
        datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None  # Invalid timestamp format

    # Check for the minimum parts required (timestamp + level)
    if len(parts) < 3:
        return None  # Missing log level part

    # Process the log level
    level_part = parts[2]
    if level_part.startswith('[') and level_part.endswith(']'):
        level = level_part[1:-1]
    else:
        level = level_part

    # Extract the message from the remaining parts
    message = ' '.join(parts[3:])

    # Return the structured dictionary
    return {
        'timestamp': timestamp_str,
        'level': level,
        'message': message
    }

