        file_path = input("Enter the path of the file to monitor: ").strip()

    if not file_path:
        print("Invalid file path provided!", file=sys.stderr)
        sys.exit(1)

    print(f"Monitoring {file_path} for modifications...")

    wm = inotifypy.WatchManager()
    event_mask = inotifypy.IN_MODIFY

    watched_file = None
    try:
        # Start watching the file
        watched_file = wm.add(path=file_path, mask=event_mask)

        # Continuously check for events
        while True:
            events = wm.read_events()
            for event in events:
                if event.type == event_mask:
                    on_file_modified(event)

    except KeyboardInterrupt:
        print("\nMonitoring stopped by user.", file=sys.stderr)
        if watched_file is not None:
            wm.remove(watched_file)
        sys.exit(0)
    except inotifypy.InotifyError as e:
        print(f"Inotify error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if watched_file is not None:
            wm.remove(watched_file)
        print("Monitoring cleanup complete.")

