        task = parts[0]
        dependencies = parts[1:]
        for dep in dependencies:
            adj[dep].append(task)
            in_degree[task] += 1

    # Kahn's algorithm
    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    sorted_order = []
    while queue:
        node = queue.popleft()
        sorted_order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

