import time

def on_file_modified(filename):
    """Callback function triggered when the file is modified."""
    print(f"File '{filename}' was modified!")

def monitor_file(filename, callback):
    """Monitors the specified file and calls the callback on modification."""
    last_modified = -1  # Initialize with a value indicating no prior modification
    while True:
        try:
            current_modified = os.path.getmtime(filename)
            if current_modified != last_modified:
                callback(filename)
                last_modified = current_modified  # Update after modification
        except OSError:  # Handle file not found or access errors
            last_modified = -2  # Sentinel value to ignore false positives
        time.sleep(0.1)  # Poll every 0.1 seconds

