import pandas as pd

def calculate_statistics(dataframe: pd.DataFrame) -> dict:
    """Calculate mean, median, mode, and sample variance for each numeric column."""
    statistics = {}
    for column in dataframe.columns:
        column_data = dataframe[column]

        # Skip non-numeric columns
        if column_data.dtype.name not in ['int64', 'float64']:
            continue

        try:
            # Compute required statistics
            mean_val = column_data.mean()
            median_val = column_data.median()
            variance_val = column_data.var(ddof=1)  # Sample variance

            # Handle mode: returns list of modes or empty list if none
            mode_series = column_data.mode()
            if mode_series.empty:
                mode_values = []
            else:
                mode_values = list(mode_series.values)

            # Store results for the column
            statistics[column] = {
                'mean': mean_val,
                'median': median_val,
                'variance': variance_val,
                'mode': mode_values
            }
        except Exception as e:
            # Log errors for debugging (omitted here for brevity)
            print(f"Error processing column {column}: {str(e)}")

    return statistics

from typing import List, Tuple
from collections import deque

def dependency_order(dependencies: List[Tuple[str, str]]) -> List[str]:
    """Return a valid execution order for tasks given their dependencies, or raise a ValueError if a cycle is detected."""
    nodes = set()
    for a, b in dependencies:
        nodes.add(a)
        nodes.add(b)

    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for a, b in dependencies:
        adj[b].append(a)
        in_degree[a] += 1

    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    return order
